s=s.replace("// hipBLAS GemmEx on gfx1151 across dtypes, output types, layouts and shapes: which variants the library runs fast\n",
"""// hipBLAS GemmEx on gfx1151 across dtypes, output types, layouts and shapes: which variants the library runs fast
// This copy: 2026-10-05-halo-gemm-variants.cpp (branch AIMAX395-ROCm) ported to cuBLAS for the RTX 3060 Laptop GPU:
// hip*/HIPBLAS_* renamed to cuda*/cublas*/CUBLAS_*, and for COMPUTE_16F alpha/beta are __half (cuBLAS, like hipBLAS,
// reads them in the compute type; a float 1.0 read as half is 0, and the library then skips the product).
// Build: nvcc -O3 -arch=sm_86 docs/benchmarks/2026-10-05-3060m-gemm-variants.cu -lcublas -o build/gemm_variants
""")
s=s.replace("#include <cublas_v2.h>\n","#include <cublas_v2.h>\n#include <cuda_fp16.h>\n")
s=s.replace("    const float alpha = 1.f, beta = 0.f;\n","    const float alpha = 1.f, beta = 0.f;\n    const __half alpha_h = __float2half(1.f), beta_h = __float2half(0.f);\n")
s=s.replace("&alpha, A, c.in","c.comp == CUBLAS_COMPUTE_16F ? (const void*) &alpha_h : (const void*) &alpha, A, c.in")
s=s.replace("&beta, C, c.out","c.comp == CUBLAS_COMPUTE_16F ? (const void*) &beta_h : (const void*) &beta, C, c.out")
open(p,'w').write(s)
EOF
